import java.util.Scanner; public class TestClass { public static void main(String[] args) { Scanner sc = new Scanner(System.in); if (!sc.hasNextInt()) return; int n = sc.nextInt(); int[] a = new int[n]; for (int i = 0; i < n; i++) { a[i] = sc.nextInt(); } int passes = 0; boolean swapped = true; while (swapped) { swapped = false; for (int i = 0; i < n - 1; i++) { if (a[i] > a[i + 1]) { int temp = a[i]; a[i] = a[i + 1]; a[i + 1] = temp; swapped = true; } } if (swapped) { passes++; } } System.out.println(passes + 1); } }